Standard exercism pig-latin problem. Implement Sentence: split by spaces, convert each word.

Algorithm per word:
- If it starts with a vowel, or starts with "xr" or "yt": append "ay".
- Otherwise, find the index where the consonant cluster ends: scan from index 0, and stop at the first vowel, or at 'y' after at least one consonant (rule 4). Also handle "qu": if the character at the consonant boundary is 'q' and the next is 'u', include the 'u' in the moved portion.

Implementation:

```go
func Sentence(sentence string) string {
    words := strings.Fields(sentence)
    out := make([]string, len(words))
    for i, w := range words {
        out[i] = translate(w)
    }
    return strings.Join(out, " ")
}

func isVowel(b byte) bool {
    switch b {
    case 'a', 'e', 'i', 'o', 'u':
        return true
    }
    return false
}

func translate(word string) string {
    if len(word) == 0 {
        return word
    }
    if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
        return word + "ay"
    }
    // Find the end of the leading consonant cluster
    i := 0
    for i < len(word) && !isVowel(word[i]) {
        if i > 0 && word[i] == 'y' {
            break
        }
        i++
    }
    // Handle "qu"
    if i < len(word) && word[i] == 'q' && i+1 < len(word) && word[i+1] == 'u' {
        i += 2
    }
    return word[i:] + word[:i] + "ay"
}
```

