package piglatin

import "strings"

// Sentence translates a sentence from English to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	translated := make([]string, len(words))
	for i, word := range words {
		translated[i] = translate(word)
	}
	return strings.Join(translated, " ")
}

func isVowel(b byte) bool {
	switch b {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

func translate(word string) string {
	if len(word) == 0 {
		return word
	}

	// Rule 1: word begins with a vowel, or starts with "xr" or "yt".
	if isVowel(word[0]) || strings.HasPrefix(word, "xr") || strings.HasPrefix(word, "yt") {
		return word + "ay"
	}

	// Rules 2 and 4: move the leading consonant cluster to the end.
	// A 'y' after at least one consonant acts as a vowel.
	i := 0
	for i < len(word) && !isVowel(word[i]) {
		if i > 0 && word[i] == 'y' {
			break
		}
		i++
	}

	// Rule 3: include a trailing "qu" in the moved prefix.
	if i > 0 && word[i-1] == 'q' && word[i] == 'u' {
		i++
	}

	return word[i:] + word[:i] + "ay"
}

